insert into public.notices (tag, title, pinned, body, sort_order) values
('필독', '비어플 출석 규칙', true, E'학회 운영 시간은 매주 토요일 10:00 - 12:00입니다.\n\n10시 30분까지는 지각 처리, 그 이후는 결석으로 처리됩니다. (지각 시 벌금 3000원, 결석 시 벌금 10000원)\n\n허용되는 불참 사유 이외의 3번 결석 시 ''삼진아웃''으로 비어플 퇴출이 진행됩니다. (허용되는 불참 사유 : 인턴, 자격증, 국가고시, 유고결석 사유)\n\n프리패스 기회를 1번 쓸 수 있습니다. 프리패스 기회란 유고결석 사유에 해당되지 않는 개인적인 사유일 때, 아무 조건 없이 사용할 수 있는 결석 면제권입니다. 사용하기 위해서는 해당 세션 3일 전까지 네이버 카페에 글을 등록해주세요.', 130),

('25-2학기', 'B.a.f 프로젝트 공지', false, E'투표 대상: 16, 17기(15기는 선택적으로 참여)\n\n투표 기한: 2024/08/29(금) 23:59\n\n투표 방법: 해당 글이 카카오톡 공지로 등록되면 댓글에 1지망과 2지망의 도메인을 작성해주시면 됩니다.\n\nex. 1지망-마케팅, 2지망-기타(의료)\n\n📌도메인:\n\n1. 금융 - 은행 채무불이행 예측, 카드거래 이상탐지 등\n\n2. 사회 - 자전거도로 입지선정, 지하철 유동인구 분석 등\n\n3. 마케팅 - 고객 세분화, 상품 추천 등\n\n4. 스포츠 - 프로야구 / e-스포츠 승률 예측 등\n\n5. 기타(의료, 환경, 공정', 120),

('25-2학기', '비어플 17기 모집 공고', false, E'안녕하세요. 통계학과 빅데이터 학회 ''비어플(B.a.f)''의 9대 회장 이선재입니다☺️\n\n🔥앞으로 다가올 2025년 2학기부터 비어플의 일원으로서 열심히 활동하실 17기 학회원을 모집하려고 합니다!🔥\n\n비어플은 동국대 유일의 빅데이터 학회로, 순수한 학문적 열망을 가진 통계학과 학생들이 자발적으로 모여 설립한 학회입니다. 저희 학회의 정기 세션은 매주 토요일 오전 10시~12시이고, 주요 활동으로는 다음과 같이 <신입교육 세션>, <프로젝트>, <특강>, <비어플의 밤>이 있습니다.\n\n✔️신입교육 세션(여름/겨울방학)\n\n프로젝트 경험이 부족한 신입 기수를 대상으로, 기본적인 프로젝트 지식과 스킬을 학습하는 세션\n\n✔️프로젝트\n\n학기 프로젝트: 1학기(3월), 2학기(9월)에 도메인별로 팀을 꾸려 데이터 수집과 주제선정부터 인사이트 도출까지 전 과정을 직접 설계하는 팀 프로젝트\n\n공모전(여름방학): 학회원끼리 팀을 꾸려 데이터 분석 관련 공모전에 참가\n\n스터디(겨울방학): 심화적인 통계 이론 및 기술을 팀원들과 함께 공부해보는 활동\n\n✔️특강\n\n졸업하신 선배님들을 초청하여 취업 후기, 현직 관련 정보 등을 공유받을 수 있는 멘토링 강연\n\n✔️비어플의 밤\n\n비어플의 연례 행사로, 졸업하신 선배님들의 취업 특강과 더불어 회식을 통해 학회원들과 졸업 기수들의 대화의 장을 마련하는 시간\n\n비어플에 대해 더 자세한 정보를 얻고 싶다면, 홈페이지와 인스타를 참고해주시기 바랍니다!\n\n📌홈페이지: https://www.dgubaf.com/\n\n📌인스타: https://www.instagram.com/bafdgu/\n\n지원서는 dgstatbaf@gmail.com으로, "이름_비어플_17기_지원서" 로 제출해주시면 됩니다. 제출 기한은 6/22(일) 23:59 까지 입니다. 모집 일정은 다음과 같습니다.\n\n- 서류 합격자 발표 : 6/24(화) 개별 합/불 문자 전송\n\n- 대면 면접 : 6/30(월) 10분 내외 간단한 면접\n\n- 최종합격자 발표 : 7/1(화) 개별 합/불 문자 전송\n\n- 신입교육세션 오리엔테이션 : 7/5(토) 10:00 (선발된 신입 기수분들은 ❗️필수로 참여❗️해 주셔야 합니다.)\n\n* 선발 기준은 최소 2학기 재학한 통계학과 학생 중 ''데이터 분석에 대한 관심 및 열정'', 그리고 ''문제 해결 능력''을 가진 모든 분들입니다. 활동 기간은 기본 3학기이나, 최소 2학기 이상 중단 없이 활동 가능한 인원 중입니다. (직전학기 지원자는 가산점을 받습니다)\n\n* 기타 문의사항은 회장 이선재, 부회장 양윤규에게로 연락 바랍니다.', 110),

('New', '수상 내역 수집 공지', false, E'안녕하세요. 모든 학회원분들께 말씀드립니다. 저희 비어플은 회원님들의 업적을 기리고, 소속 회원들의 도전 의욕을 불태우기 위해 2024년도 수상 내역을 수집하고자 합니다. 아직 수상 경험이 없으신 분들도 향후 대회에서 입상하시게 되면, 저희에게 알려주시면 감사하겠습니다. 수집된 수상 내역은 비어플 홈페이지와 향후 개설될 카페에도 올라갈 예정입니다.\n\n아래는 수집에 대한 세부 사항입니다.\n\n* 대상: 비어플의 모든 기수\n\n* 제출 방법: https://forms.gle/V3dLgHmGFpxmcExn7 \n\n* 제출 기한 : 12/31(화) 23:59\n\n* 제출 내용: 수상자, 수상 대회(예: SAS 분석 챔피언십 등), 수상 종류(예: 대상, 최우수상 등), 수상 관련 사진 또는 기록(선택), 수상에 사용된 자료(선택)\n\n수집된 정보는 비어플 홍보 및 회원들의 도전 의지 고취에 활용될 예정입니다. 많은 참여 부탁드립니다. 감사합니다.🙇\n\n* 수상자의 경우 비어플 학회원이 한 명이라도 포함되면 됩니다. 홈페이지에 올라가다 보니 다른 수상자분들의 동의하에 제공해주시면 감사하겠습니다.\n\n* 세부적인 사항은 링크에 자세히 적혀있으니 확인해주시면 감사하겠습니다.\n\n* 추가적인 문의 사항은 임원진에게 연락 바랍니다.', 100),

('25-1학기', '비어플 16기 모집 공고', false, E'안녕하세요. 통계학과 빅데이터 학회 ''비어플(B.a.f)''의 9대 회장 이선재입니다☺️\n\n🔥앞으로 다가올 2025년 1학기부터 비어플의 일원으로서 열심히 활동하실 16기 학회원을 모집하려고 합니다!🔥\n\n비어플은 동국대 유일의 빅데이터 학회로, 순수한 학문적 열망을 가진 통계학과 학생들이 자발적으로 모여 설립한 학회입니다. 저희 학회의 정기 세션은 매주 토요일 오전 10시~12시이고, 주요 활동으로는 다음과 같이 <세션>, <프로젝트>, <특강>, <비어플의 밤>이 있습니다.\n\n✔️세션\n\n- 신입교육 세션: 프로젝트 경험이 부족한 신입 기수를 대상으로, 기본적인 프로젝트 지식과 스킬을 학습하는 세션\n\n- 피드백 세션: 프로젝트, 공모전, 스터디가 끝난 후, 부족한 부분을 보충하는 세션\n\n✔️프로젝트\n\n- 학기 프로젝트: 1학기(3월), 2학기(9월)에 특정 분석 주제를 가지고 데이터 분석을 해보는 팀 프로젝트\n\n- 공모전: 학회원이 참가를 희망하는 공모전이 개최될 시, 팀을 꾸려 대회에 참가\n\n- 스터디: 심화적인 통계 이론 및 기술을 팀원들과 함께 공부해보는 활동\n\n✔️특강\n\n- 졸업하신 선배님들을 초청하여 취업 후기, 현직 관련 정보 등을 공유받을 수 있는 멘토링 강연\n\n✔️비어플의 밤\n\n- 비어플의 연례 행사로, 졸업하신 선배님들의 취업 특강과 더불어 회식을 통해 학회원들과 졸업 기수들의 대화의 장을 마련하는 시간\n\n비어플에 대해 더 자세한 정보를 얻고 싶다면, 홈페이지와 인스타를 참고해주시기 바랍니다!\n\n📌홈페이지: https://www.dgubaf.com/\n\n📌인스타: https://www.instagram.com/bafdgu/\n\n지원서는 dgstatbaf@gmail.com으로, "이름_비어플_16기_지원서" 로 제출해주시면 됩니다. 제출 기한은 12/16(월) 23:59 까지 입니다. 서류 심사이며, 선발자는 12/23(월)에 개별 공지 예정입니다. 많은 관심과 지원 바랍니다!🤗\n\n선발 기준은 최소 2학기 재학한 통계학과 학생 중 ''데이터 분석에 대한 관심 및 열정'', 그리고 ''문제 해결 능력''을 가진 모든 분들입니다. 활동 기간은 기본 3학기이나, 최소 2학기 이상 중단 없이 활동 가능한 인원 중입니다. (직전학기 지원자는 가산점을 받습니다)\n\n신입 OT는 01/11(토) 16:00입니다. 선발된 신입 기수분들은 ❗️필수로 참여❗️해 주셔야 합니다.\n\n** 기타 문의사항은 회장 이선재, 부회장 양윤규에게로 연락 바랍니다.', 90),

('24-2학기', 'B.a.f 프로젝트 공지', false, E'이번 프로젝트에서는 24-1학기 프로젝트와 마찬가지로, 학회원들의 보다 자유롭고 창의적인 진행을 위해 데이터 및 주제는 제공되지 않습니다. 세부 주제는 조원 확정 후 정하시면 됩니다. 이번 주 금요일 팀 확정 공지가 있을 예정입니다.\n\n투표 대상: 14, 15기(13기는 선택적으로 참여)\n\n투표 기한: 2024/09/04(수) 23:59\n\n투표 방법: 해당 글이 공지로 등록되면 댓글에 1지망과 2지망의 도메인을 작성해주시면 됩니다.\n\nex. 1지망-마케팅, 2지망-기타(환경)\n\n📌도메인:\n\n1. 금융 - 은행 채무불이행 예측, 카드거래 이상탐지 등 \n\n2. 사회 - 자전거도로 입지선정, 지하철 유동인구 분석 등 \n\n3. 마케팅 - 고객 세분화, 상품 추천 등\n\n4. 스포츠  - 프로야구 / e-스포츠  승률 예측 등 \n\n5. 기타(의료, 환경, 공정 등) - 위의 도메인이 아닌 경우\n\n* 원활한 조원 배치를 위해 도메인별 인원 제한이 있을 예정입니다. 특정 도메인에 인원이 많을 시 선착순으로 조원이 배정될 수 있습니다.', 80),

('24-1학기', 'B.a.f 프로젝트 공지', false, E'이번 프로젝트에서는 학회원들의 보다 자유롭고 창의적인 진행을 위해 데이터는 제공되지 않습니다. 세부 주제는 조원 확정 후 정하면 됩니다.\n\n투표 대상: 13, 14기(12기는 선택적으로 참여)\n\n투표 기한: 2024/03/03(일) 23:59:59 \n\n투표 방법: 해당 글이 공지로 등록되면 댓글에 1지망과 2지망의 주제를 작성해주시면 됩니다.\n\n📌주제:\n\n1. 게임 - 다양한 게임 데이터\n\n2. 금융 - 주식, 카드 소비, 보험 등 금융 데이터\n\n3. 의료 - 질병, 생존, 의약품 등 의료 데이터\n\n4. 쇼핑 - 상품 구매 등  쇼핑 데이터\n\n5. 환경 - 에너지, 기상 예측, 환경 오염 등 환경 데이터\n\n6. 사회 - 행복주택 입지선정, 지하철 등 사회 데이터\n\n7. 기타 - 위의 주제들이 아닌 데이터\n\n*  원활한 조원 배치를 위해 도메인별 인원 제한이 있을 예정입니다. 특정 도메인에 인원이 많을 시 선착순으로 조원이 배정될 수 있습니다.', 70),

('23-2학기', '❄️ 겨울방학 스터디 공지', false, E'여러분 얼마 안 남은 2023년 연말 잘 보내시고 계신가요? 모두들 새해 복 많이 받으시길 바랍니다!!🙇\n\n이번주부터 겨울방학 스터디를 진행하려고 합니다.\n\n다음 노션 링크를 통해, 본인이 원하는 주제란에 ''이름''과 ''선택한 이유''를 적어주시면 됩니다. 최종 팀은 1/3(수)에 공지됩니다. \n\n📌노션 링크: https://www.notion.so/baf-dongguk/2023-021065c5853543b28d011b5aeeead04d?pvs=4  \n\n📌대상: 활동기수 (신입기수 14기 제외)\n\n📌마감 기한: 1/3(수) 오후 6시까지 \n\n각 팀별로 임원진이 한 명씩 배정되고, 팀 내에서 세부 주제와 커리큘럼을 직접 설정할 예정입니다. 자세한 사항은 1/6(토)에 안내드리겠습니다. \n\n* 각 주제의 투표 수에 따라 팀 구성은 바뀔 수 있습니다.\n\n** 궁금한 점이나 문의사항 있으신 분들은 임원진들에게 연락주시길 바랍니다.', 60),

('New', '비어플 14기 모집 공고', false, E'안녕하세요. 통계학과 빅데이터 학회 ''비어플(B.a.f)''의 8대 회장 문성원입니다☺️\n\n🔥앞으로 다가올 2024년부터 비어플의 일원으로서 열심히 활동하실 14기 학회원을 모집하려고 합니다!🔥\n\n 비어플은 동국대 유일의 빅데이터 학회로, 순수한 학문적 열망을 가진 통계학과 학생들이 자발적으로 모여 설립한 학회입니다. 저희 학회의 정기 세션은 매주 토요일 오전 10시~12시이고, 주요 활동으로는 다음과 같이 <세션>, <프로젝트>, <특강>, <비어플의 밤>이 있습니다.\n\n✔️세션\n\n- 신입교육 세션: 프로젝트 경험이 부족한 신입 기수를 대상으로, 기본적인 프로젝트 지식과 스킬을 학습하는 세션\n\n- 피드백 세션: 프로젝트, 공모전, 스터디가 끝난 후, 부족한 부분을 보충하는 세션\n\n✔️프로젝트\n\n- 학기 프로젝트: 1학기(3월), 2학기(9월)에 특정 분석 주제를 가지고 데이터 분석을 해보는 팀 프로젝트\n\n- 공모전: 학회원이 참가를 희망하는 공모전이 개최될 시, 팀을 꾸려 대회에 참가\n\n- 스터디: 심화적인 통계 이론 및 기술을 팀원들과 함께 공부해보는 활동\n\n✔️특강\n\n- 졸업하신 선배님들을 초청하여 취업 후기, 현직 관련 정보 등을 공유받을 수 있는 멘토링 강연\n\n✔️비어플의 밤\n\n- 비어플의 연례 행사로, 졸업하신 선배님들의 취업 특강과 더불어 회식을 통해 학회원들과 졸업 기수들의 대화의 장을 마련하는 시간\n\n 비어플에 대해 더 자세한 정보를 얻고 싶다면, 홈페이지와 인스타를 참고해주시기 바랍니다!\n\n📌홈페이지: https://www.dgubaf.com/ \n\n📌인스타: https://www.instagram.com/dgubaf/ \n\n 지원서는 dgstatbaf@gmail.com으로, "이름_비어플_14기_지원서" 로 제출해주시면 됩니다. 제출 기한은 12/22(금) 자정까지 입니다. 서류 심사이며, 선발자는 12/26(화)에 개별 공지 예정입니다.\n\n많은 관심과 지원 바랍니다!🤗\n\n* 선발 기준은 ''데이터 분석에 대한 관심 및 열정'', ''문제 해결 능력'', ''남은 학기 수'', 그리고 ''참여 기회''입니다. 활동 기간은 기본 3학기이나, 최소 2학기 이상, 도중 중단 없이 활동 가능한 인원 중에서, 직전학기 지원자 이거나 기회가 적은 인원은 가산점을 받습니다.\n\n** 신입 OT는 12/29(금) 16:00입니다. 선발된 신입 기수분들은 ❗️필수로 참여❗️해 주셔야 합니다.\n\n*** 기타 문의사항은 회장 문성원, 부회장 이예슬에게로 연락 바랍니다.', 50),

('공지', '🏆 역대 수상 내역 수집 공지', false, E'안녕하세요. 모든 학회원분들께 말씀드립니다. 저희 비어플은 회원님들의 업적을 기리고, 소속 회원들의 도전 의욕을 불태우기 위해 역대 수상 내역을 수집하고자 합니다. 아직 수상 경험이 없으신 분들도 향후 대회에서 입상하시게 되면, 저희에게 알려주시면 감사하겠습니다. 수집된 수상 내역은 비어플 홈페이지와 향후 개설될 카페에도 올라갈 예정입니다.\n\n아래는 수집에 대한 세부 사항입니다.\n\n* 대상: 비어플의 모든 기수\n\n* 제출 방법: https://forms.gle/oRmTLc5wSHGu3EJu9 \n\n* 제출 내용: 수상자, 수상 대회(예: SAS 분석 챔피언십 등), 수상 종류(예: 대상, 최우수상 등), 수상 관련 사진 또는 기록(선택), 수상에 사용된 자료(선택)\n\n수집된 정보는 비어플 홍보 및 회원들의 도전 의지 고취에 활용될 예정입니다. 많은 참여 부탁드립니다. 감사합니다.🙇\n\n* 수상자의 경우 비어플 학회원이 한 명이라도 포함되면 됩니다. 홈페이지에 올라가다 보니 다른 수상자분들의 동의하에 제공해주시면 감사하겠습니다.\n\n* 세부적인 사항은 링크에 자세히 적혀있으니 확인해주시면 감사하겠습니다.\n\n* 추가적인 문의 사항은 임원진에게 연락 바랍니다.', 40),

('23-2학기', '피드백 스터디 발표 공지', false, E'안녕하세요. 이번 주 활동 공지입니다.\n\n피드백 스터디 발표는 10분~15분이고 모든 팀원이 내용을 숙지해야 합니다. 제출 방법은 아래의 링크를 통해 노션에 제출해주시면 됩니다.\n\n아래는 세부 사항입니다.\n\n일시: 12/2(토) 오전 10시\n\n장소: 과학관 AH실\n\n대상: 12, 13기\n\n제출 기한: ~ 12월 1일(금) 오후 11시\n\n공유링크: https://baf-dongguk.notion.site/15920d5b69e74149a6c68a125ac7893a?pvs=4 \n\n* 참석이 어려우신 분은 미리 연락 바랍니다.', 30),

('23-2학기', '프로젝트 일정변경 공지', false, E'안녕하세요. 길었던 명절 연휴가 지나갔습니다. 모두 즐거운 연휴 되셨기를 바라고 일상 복귀에 잘 적응하시기를 바랍니다.\n\n최종 자료 제출 일정에 변경이 있어 안내드립니다. NH조의 공모전 마감이 17일이고, 연휴도 있었기 때문에 시간적 여유를 드리기 위해 프로젝트 최종 마감일을 조금 늦추려 합니다.\n\n기존 제출 일시 : ~2023.10.14.(토) 자정\n\n📌변경 후 제출 일시 : ~2023.10.18.(수) 자정\n\n제출 유형 : ppt를 pdf로 변환하여 제출\n\n제출 기한 : 2023.10.18.(수) 자정\n\n제출 링크 : https://plain-cosmonaut-e71.notion.site/9f7f571a7d764c259024ac5874176b2c?pvs=4  \n\n* ppt 이외의 양식은 허용되지 않으며 반드시 쪽수가 포함되어야 합니다.\n\n* 최종 발표 자료에는 코드가 포함되지 않아야 합니다.\n\n* 따로 문의하실 사항은 임원진에게 연락 바랍니다.', 20);

