insert into public.materials (type, title, description, author, mat_date, tags, sort_order) values
('edu', '크롤링 강의안', '페이스북, 트위터에서 토큰을 부여받아 크롤링하는 방법부터 웹데이터 페이지 소스 활용까지 다룹니다.', '13 이동현', '2017.09.29', ARRAY['Facebook','Twitter','웹데이터'], 60),
('edu', 'Textmining 문자열 정제 추가강의안', 'R을 활용한 텍스트마이닝 문자열 정제 심화 내용을 다룹니다.', '13 이동현', '2017.09.29', ARRAY['R','Textmining','전처리'], 50),
('edu', '기본적인 Textmining 입문강의안', 'R 프로그램으로 시작하는 텍스트마이닝 입문 강의안입니다.', '13 이동현', '2017.09.15', ARRAY['R','Textmining','입문'], 40),
('project', '인적자원분석 — 이직여부 예측', 'EDA를 바탕으로 이직 가능성에 영향을 주는 요인을 분석하고 예측 모형을 구축했습니다.', '김현중, 이정, 박권수, 정아현', '2017.11.26', ARRAY['EDA','로지스틱 회귀분석','랜덤 포레스트'], 30),
('project', 'League of Legends 승패예측 및 연관성분석', '경기 로그 텍스트를 마이닝해 승패에 기여하는 변수와 아이템 간 연관 규칙을 도출했습니다.', '이동현, 김준섭, 양준혁, 양동찬', '2017.11.26', ARRAY['텍스트마이닝','로지스틱 회귀분석','연관성분석'], 20),
('project', '유방암세포 진단결과 예측모형 구축', '세포 형태 지표를 활용해 양성·악성을 분류하는 진단 예측모형을 설계했습니다.', '오현지, 황인욱, 황다연, 윤인선', '2017.11.26', ARRAY['EDA','로지스틱 회귀분석','의사결정나무'], 10);

