insert into public.faqs (question, answer, sort_order) values
('새로운 기수는 언제 모집하나요?', '신입 기수 모집은 매년 6월과 12월 중순에 진행됩니다. 모집 공고는 통계학과 학년별 단체 채팅방을 통해 안내되니 참고 바랍니다.', 30),
('학년 제한이 있나요?', '비어플 지원은 2학년 1학기까지를 수료하신 후 할 수 있습니다.', 20),
('세션은 어디서 진행되나요?', '세션은 대면으로 진행되며, 과학관 AH 실습실에서 10:00 - 12:00까지 진행합니다.', 10);
